const rows=computed(()=>[['粉丝规模','22.4w','清华优优','18.7w',peer.value.name],['近 30 日发布','12','短视频 + 直播','9','短视频为主'],['平均观看','4.8w','以选题带动','6.2w','爆款集中'],['互动率','7.6%','评论提问引导','9.1%','强钩子结构']])
